- (void)viewDidLoad{[super viewDidLoad];self.overrideUserInterfaceStyle=UIUserInterfaceStyleDark;self.view.backgroundColor=PVXDark(17);self.rows=@[];self.allRows=@[];self.selection=[NSMutableSet set];self.pending=[NSMutableSet set];self.closeButton=[self button:@"xmark" label:@"关闭下载管理" action:@selector(close)];self.settingsButton=[self button:@"gearshape" label:@"下载设置" action:@selector(settings)];self.selectButton=[self button:@"checkmark.square" label:@"选择任务" action:@selector(selectTasks)];self.imagesButton=[UIButton buttonWithType:UIButtonTypeSystem];[self.imagesButton setTitle:@"图片" forState:UIControlStateNormal];[self.imagesButton addTarget:self action:@selector(images) forControlEvents:UIControlEventTouchUpInside];self.tabs=[[UISegmentedControl alloc] initWithItems:@[@"下载",@"采集"]];self.tabs.selectedSegmentIndex=0;[self.tabs setTitleTextAttributes:@{NSFontAttributeName:[UIFont systemFontOfSize:17 weight:UIFontWeightBold]} forState:UIControlStateNormal];[self.tabs addTarget:self action:@selector(tabChanged) forControlEvents:UIControlEventValueChanged];self.storage=[UIProgressView new];self.storage.progressTintColor=UIColor.systemRedColor;self.storage.trackTintColor=UIColor.systemBlueColor;self.storageLabel=[UILabel new];self.storageLabel.textColor=UIColor.whiteColor;self.storageLabel.textAlignment=NSTextAlignmentCenter;self.storageLabel.font=[UIFont systemFontOfSize:10 weight:UIFontWeightSemibold];self.search=[UISearchBar new];self.search.placeholder=@"搜索标题或者 URL";self.search.searchBarStyle=UISearchBarStyleMinimal;self.search.searchTextField.backgroundColor=PVXDark(23);self.search.delegate=self;self.sectionLabel=[UILabel new];self.sectionLabel.font=[UIFont systemFontOfSize:17 weight:UIFontWeightBold];self.sectionLabel.textColor=UIColor.whiteColor;self.sectionLabel.userInteractionEnabled=YES;[self.sectionLabel addGestureRecognizer:[[UITapGestureRecognizer alloc] initWithTarget:self action:@selector(collapse)]];self.table=[[UITableView alloc] initWithFrame:CGRectZe