- (void)viewDidLayoutSubviews{[super viewDidLayoutSubviews];UIEdgeInsets s=self.view.safeAreaInsets;CGFloat w=self.view.bounds.size.width,y=s.top+5;self.closeButton.frame=CGRectMake(s.left+5,y,44,44);self.tabs.frame=CGRectMake(s.left+55,y+3,MIN(160,w-210),38);self.selectButton.frame=CGRectMake(w-s.right-90,y,44,44);self.settingsButton.frame=CGRectMake(w-s.right-46,y,44,44);y+=51;self.storage.frame=CGRectMake(0,y,w,15);self.storage.transform=CGAffineTransformMakeScale(1,4);self.storageLabel.frame=CGRectMake(8,y-7,w-16,20);y+=14;self.search.frame=CGRectMake(s.left,y,w-s.left-s.right,52);y+=52;self.sectionLabel.frame=CGRectMake(s.left+12,y,w-s.left-s.right-100,44);self.imagesButton.frame=CGRectMake(w-s.right-78,y,72,44);y+=44;self.table.frame=CGRectMake(s.left,y,w-s.left-s.right,self.view.bounds.size.height-y-s.bottom);}
- (void)viewDidAppear:(BOOL)animated{[super viewDidAppear:animated];self.visible=YES;__weak typeof(self)weak=self;self.timer=[NSTimer scheduledTimerWithTimeInterval:1 repeats:YES block:^(NSTimer *t){if(weak.visible&&weak.view.window&&UIApplication.sharedApplication.applicationState==UIApplicationStateActive)[weak reload];}];[self reload];}
