- (void)close{[self dismissViewControllerAnimated:YES completion:nil];}
- (void)images{PVXShowImages();}
- (void)collapse{self.collapsed=!self.collapsed;[self filter];}
- (void)tabChanged{self.collapsed=NO;self.selecting=NO;[self.selection removeAllObjects];[self refresh];}
- (void)refresh{id b=PVXBrowser();SEL refresh=NSSelectorFromString(@"refresh");if([b respondsToSelector:refresh])((void(*)(id,SEL))objc_msgSend)(b,refresh);[self reload];[self.table.refreshControl endRefreshing];}
- (void)reload{if(self.reading)return;if(self.tabs.selectedSegmentIndex==1){id v=PVXGet(PVXBrowser(),@"candidates");self.allRows=[v isKindOfClass:NSArray.class]?v:@[];[self filter];return;}self.reading=YES;dispatch_async(dispatch_get_global_queue(QOS_CLASS_UTILITY,0),^{NSArray *rows=PVXReadVideoTasks();NSDictionary *disk=[NSFileManager.defaultManager attributesOfFileSystemForPath:PVXStateRoot() error:nil];dispatch_async(dispatch_get_main_queue(),^{self.reading=NO;if(self.tabs.selectedSegmentIndex!=0)return;self.allRows=rows;unsigned long long total=[disk[NSFileSystemSize] unsignedLongLongValue],free=[disk[NSFileSystemFreeSize] unsignedLongLongValue],used=total-MIN(total,free);self.storage.progress=total?(float)((double)used/total):0;self.storageLabel.text=total?[NSString stringWithFormat:@"已使用 %@ / %@",[NSByteCountFormatter stringFromByteCount:used countStyle:NSByteCountFormatterCountStyleFile],[NSByteCountFormatter stringFromByteCount:total countStyle:NSByteCountFormatterCountStyleFile]]:@"存储空间读取中";[self filter];});});}
- (void)filter{NSString *q=self.search.text?:@"";self.rows=[self.allRows filteredArrayUsingPredicate:[NSPredicate predicateWithBlock:^BOOL(id r,NSDictionary *bindings){if(![r isKindOfClass:NSDictionary.class])return NO;return !q.length||[PVXDText(r[@"title"]) localizedCaseInsensitiveContainsString:q]||[PVXDText(r[@"url"]) localizedCaseInsensitiveContainsString:q];}]];self.sectionLabel.text=[NSString stringWithFormat:@"%@ %@ (%lu)",self.collapsed?@"▸":@"▾",self.tabs.selectedSegmentIndex==0?@"我的下载":@"当前页面",(unsigned long)self.rows.count];[self.table reloadData];if(!self.rows.count){UILabel *empty=[UILabel new];empty.text=self.tabs.selectedSegmentIndex==0?@"暂无下载任务":@"先播放视频，再下拉重新采集";empty.textColor=UIColor.secondaryLabelColor;empty.textAlignment=NSTextAlignmentCenter;self.table.backgroundView=empty;}else self.table.backgroundView=nil;}
- (void)searchBar:(UISearchBar*)bar textDidChange:(NSString*)text{[self filter];}
- (void)searchBarSearchButtonClicked:(UISearchBar*)bar{[bar resignFirstResponder];}
- (NSInteger)tableView:(UITableView*)table numberOfRowsInSection:(NSInteger)section{return self.collapsed?0:self.rows.count;}
- (UITableViewCell*)tableView:(UITableView*)table cellForRowAtIndexPath:(NSIndexPath*)path{PVXDownloadCell *cell=[table dequeueReusableCellWithIdentifier:@"download" forIndexPath:path];NSDictionary *r=self.rows[path.row];NSString *identity=PVXDIdentity(r);if(![identity isEqual:cell.identity]){cell.identity=identity;cell.requested=NO;cell.cover.image=[UIImage systemImageNamed:@"play.rectangle"];cell.cover.contentMode=UIViewContentModeScaleAspectFit;}BOOL collect=self.tabs.selectedSegmentIndex==1;NSDictionary *p=collect?@{@"status":[self.pending containsObject:identity]?@"正在提交":@"点击下载",@"symbol":@"arrow.down.circle.fill",@"tint":UIColor.systemBlueColor,@"size":PVXDText(r[@"page"]),@"format":@"mp4",@"progress":@0}:PVXTaskPresentation(r);cell.title.text=PVXDText(r[@"title"]).length?r[@"title"]:@"视频";cell.status.text=p[@"status"];cell.statusIcon.image=[UIImage systemImageNamed:p[@"symbol"]];cell.statusIcon.tintColor=p[@"tint"];cell.format.text=p[@"format"];cell.size.text=p[@"size"];cell.progress.progress=[p[@"progress"] floatValue];cell.progress.hidden=collect||![@[@"downloading",@"hls",@"converting",@"remuxing"] containsObject:r[@"state"]];cell.more.menu=[self menuFor:r anchor:cell.more];cell.accessoryType=self.selecting&&[self.selection containsObject:identity]?UITableViewCellAccessoryCheckmark:UITableViewCellAccessoryNone;if(!cell.requested){cell.requested=YES;__weak PVXDownloadCell *weak=cell;PVXFetchTaskThumbnail(r,^(UIImage *image){if(image&&[weak.identity isEqual:identity]){weak.cover.image=image;weak.cover.contentMode=UIViewContentModeScaleAspectFill;}});}return cell;}
- (UIAction*)action:(NSString*)title symbol:(NSString*)symbol perform:(void(^)(void))handler{return [UIAction actionWithTitle:title image:[UIImage systemImageNamed:symbol] identifier:nil handler:^(UIAction *a){handler();}];}
- (UIMenu*)menuFor:(NSDictionary*)r anchor:(UIButton*)button{NSMutableArray *actions=[NSMutableArray array];__weak typeof(self)weak=self;BOOL image=[r[@"kind"] isEqual:@"image"];NSString *state=r[@"state"];if(self.tabs.selectedSegmentIndex==1){[actions addObject:[self action:@"下载视频" symbol:@"arrow.down.circle" perform:^{[weak download:r];}]];}else{if(!image){if([@[@"downloading",@"queued",@"hls",@"remuxing",@"converting",@"checking",@"ready"] containsObject:state])[actions addObject:[self action:@"暂停" symbol:@"pause.circle" perform:^{PVXTaskAction(r,@"pause");}]];if([state isEqual:@"paused"])[actions addObject:[self action:@"继续下载" symbol:@"play.circle" perform:^{PVXTaskAction(r,@"resume");}]];if([@[@"failed",@"albumFailed"] containsObject:state])[actions addObject:[self action:@"重试" symbol:@"arrow.clockwise" perform:^{PVXTaskAction(r,@"retry");}]];}if(PVXTaskHasLocalFile(r)){[actions addObject:[self action:@"保存到文件" symbol:@"folder" perform:^{PVXExportTaskToFiles(r);}]];if([state isEqual:@"ready"]||(image&&[state isEqual:@"failed"]))[actions addObject:[self action:@"保存到相册" symbol:@"photo" perform:^{PVXSaveTaskToPhotos(r);}]];}if(!image){UIAction *delete=[self action:@"删除任务及本地文件" symbol:@"trash" perform:^{PVXTaskAction(r,@"delete");}];delete.attributes=UIMenuElementAttributesDestructive;[actions addObject:delete];}}if(PVXDText(r[@"error"]).length)[actions addObject:[self action:@"查看失败原因" symbol:@"exclamationmark.circle" perform:^{PVXAlert(@"任务信息",r[@"error"]);}]];return [UIMenu menuWithTitle:@"" children:actions];}
- (void)tableView:(UITableView*)table didSelectRowAtIndexPath:(NSIndexPath*)path{[table deselectRowAtIndexPath:path animated:YES];NSDictionary *r=self.rows[path.row];if(self.tabs.selectedSegmentIndex==1){[self download:r];return;}if(self.selecting&&![r[@"kind"] isEqual:@"image"]){NSString *key=PVXDIdentity(r);if([self.selection containsObject:key])[self.selection removeObject:key];else[self.selection addObject:key];[self.table reloadRowsAtIndexPaths:@[path] withRowAnimation:UITableViewRowAnimationNone];}}
- (void)download:(NSDictionary*)candidate{NSString *key=PVXDIdentity(candidate);if([self.pending containsObject:key])return;id b=PVXBrowser();SEL sel=NSSelectorFromString(@"download:completion:");if(![b respondsToSelector:sel]){PVXAlert(@"采集尚未就绪",@"请重新打开 Safari 页面。");return;}[self.pending addObject:key];[self filter];__weak typeof(self)weak=self;((void(*)(id,SEL,id,id))objc_msgSend)(b,sel,candidate,^(NSString *error){dispatch_async(dispatch_get_main_queue(),^{[weak.pending removeObject:key];if(error.length)PVXAlert(@"下载未提交",error);else{weak.tabs.selectedSegmentIndex=0;[weak tabChanged];}});});}
- (void)settings{UIAlertController *a=[UIAlertController alertControllerWithTitle:@"下载设置" message:PVXAutoSavePhotos()?@"自动保存到相册：开启\n下载原文件同时保留，可另存到“文件”。":@"自动保存到相册：关闭\n下载完成保留本地文件，可手动存相册或“文件”。" preferredStyle:UIAlertControllerStyleActionSheet];[a addAction:[UIAlertAction actionWithTitle:PVXAutoSavePhotos()?@"关闭自动存相册":@"开启自动存相册" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){PVXSetAutoSavePhotos(!PVXAutoSavePhotos());}]];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];a.popoverPresentationController.sourceView=self.settingsButton;a.popoverPresentationController.sourceRect=self.settingsButton.bounds;[self presentViewController:a animated:YES completion:nil];}
- (void)selectTasks{if(self.tabs.selectedSegmentIndex!=0)return;if(!self.selecting){self.selecting=YES;[self.selection removeAllObjects];[self.selectButton setImage:[UIImage systemImageNamed:@"trash"] forState:UIControlStateNormal];[self filter];return;}if(!self.selection.count){self.selecting=NO;[self.selectButton setImage:[UIImage systemImageNamed:@"checkmark.square"] forState:UIControlStateNormal];[self filter];return;}NSMutableArray *selected=[NSMutableArray array];for(NSDictionary *r in self.rows)if([self.selection containsObject:PVXDIdentity(r)]&&![r[@"kind"] isEqual:@"image"])[selected addObject:r];UIAlertController *a=[UIAlertController alertControllerWithTitle:[NSString stringWithFormat:@"删除 %lu 项任务？",(unsigned long)selected.count] message:@"会停止下载并删除本地文件，已存入相册的项目保持不变。" preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[a addAction:[UIAlertAction actionWithTitle:@"删除" style:UIAlertActionStyleDestructive handler:^(UIAlertAction *x){for(NSDictionary *r in selected)PVXTaskAction(r,@"delete");self.selecting=NO;[self.selection removeAllObjects];[self.selectButton setImage:[UIImage systemImageNamed:@"checkmark.square"] forState:UIControlStateNormal];[self reload];}]];[self presentViewController:a animated:YES completion:nil];}
@end
static __weak PVXDownloads *PVXVisibleDownloads;
